import type { NonEmpty } from "nonempty";
import wordsJson from "../words.json" with { type: "json" };

// Cast at the import boundary — `words.json` is regenerated by
// `just regenerate` in this package, so empty is a build-time failure,
// not a runtime one.
const adjectives = wordsJson.adjectives as unknown as NonEmpty<string>;
const nouns = wordsJson.nouns as unknown as NonEmpty<string>;

function pick(list: NonEmpty<string>): string {
  const idx = Math.floor(Math.random() * list.length);
  return list[idx] ?? list[0];
}

/** Generate a random ADJ-NOUN name (e.g. "bright-falcon"). */
export function randomName(): string {
  return `${pick(adjectives)}-${pick(nouns)}`;
}
